function v101ContactRadius(e){return Math.max(18,Math.round(e.r*.58+10))}
function v101EnemyHitRadius(e){return e.r+(e.kind==='boss'?42*v173iBossScale(e.v06BossId):e.kind==='elite'?28:18)}
