 build.counts??={};for(const [k,v] of Object.entries(otherBuild.counts||{}))build.counts[k]=(build.counts[k]||0)+v;
 // Relics are unbound from the consumed partner and carried into vacant slots.
 for(let i=v107Relics(p).length-1;i>=0;i--)v107RemoveRelic(p,i);
