 v102Catalog.classList.toggle('codex-all',mode==='all');
 $('#codexTreeMode').setAttribute('aria-pressed',String(mode==='tree'));
 $('#codexAllMode').setAttribute('aria-pressed',String(mode==='all'));
 const search=$('#codexSearch');search.placeholder=mode==='all'?'수록 디지몬 이름 검색':'디지몬 이름으로 계통 검색';
