// Agumon skill FX test. Visuals only: original projectile movement,
// hitboxes, damage, status stacks and hit sounds remain authoritative.
const AGFX_DATA={"agumon_explosion_large_01":"data:image/png;base64,","agumon_explosion_large_02":"data:image/png;base64,","agumon_explosion_large_03":"data:image/png;base64,","agumon_explosion_large_04":"data:image/png;base64,","agumon_explosion_large_05":"data:image/png;base64,","agumon_explosion_large_06":"data:image/png;base64,","agumon_explosion_small_01":"data:image/png;base64,","agumon_explosion_small_02":"data:image/png;base64,","agumon_explosion_small_03":"data:image/png;base64,","agumon_explosion_small_04":"data:image/png;base64,","agumon_explosion_small_05":"data:image/png;base64,","agumon_fireball_large_01_right":"data:image/png;base64,","agumon_fireball_large_02_right":"data:image/png;base64,","agumon_fireball_large_03_right":"data:image/png;base64,","agumon_fireball_large_04_right":"data:image/png;base64,","agumon_fireball_small_01_right":"data:image/png;base64,","agumon_fireball_small_02_right":"data:image/png;base64,","agumon_fireball_small_03_right":"data:image/png;base64,","agumon_fireball_small_04_right":"data:image/png;base64,"};
const agfxFrames={};
for(const [key,uri] of Object.entries(AGFX_DATA)){
 const image=new Image();image.src=uri;agfxFrames[key]=image;
}
function agfxReady(kind,index){const key='agumon_'+kind+'_'+String(index).padStart(2,'0')+(kind.startsWith('fireball')?'_right':'');const im=agfxFrames[key];return im?.complete&&im.naturalWidth?im:null}
function agfxMark(p,kind){
 if(!p||p.owner?.form!=='agumon'||p.enemy||!p.explode)return;
 p.agfxKind=kind;p.agfxClock=0;
}
const AGFX_skillE=skillE;
skillE=function(c,...args){
 const before=projectiles.length,result=AGFX_skillE(c,...args);
 if(c?.form==='agumon')for(const p of projectiles.slice(before))if(p.owner===c)agfxMark(p,'small');
 return result;
};
const AGFX_updateUltimate=updateUltimate;
updateUltimate=function(dt){
 const u=ultimateState,before=projectiles.length,result=AGFX_updateUltimate(dt);
 if(u?.c?.form==='agumon')for(const p of projectiles.slice(before))if(p.owner===u.c)agfxMark(p,p.r>16?'large':'small');
 return result;
};
const AGFX_projectiles=updateProjectiles;
updateProjectiles=function(dt,ultOnly){
 const candidates=projectiles.filter(p=>p.agfxKind&&p.life>0);
 for(const p of candidates)p.agfxClock+=dt;
 const before=effects.length,result=AGFX_projectiles(dt,ultOnly);
 const consumed=candidates.filter(p=>p.life<=0);
 for(const ef of effects.slice(before)){
  if(ef.type!=='burst')continue;
  // Bosses have generous hit radii: a collision can happen well before the
  // projectile reaches their center, where the existing explosion is drawn.
  const p=consumed.find(q=>q.explode&&Math.abs(q.explode-ef.r)<.01&&q.color===ef.color&&Math.hypot(q.x-ef.x,q.y-ef.y)<Math.max(250,q.explode+150));
  if(!p)continue;
  ef.agfxKind=p.agfxKind;
  ef.total=ef.t=p.agfxKind==='large'?.42:.32;
  // A single projectile can only own its own impact animation.
  consumed.splice(consumed.indexOf(p),1);
 }
 return result;
};
const AGFX_drawProjectile=drawProjectileV4;
drawProjectileV4=function(p){
 if(!p.agfxKind)return AGFX_drawProjectile(p);
 const frame=1+Math.floor((p.agfxClock||0)/.09)%4,im=agfxReady('fireball_'+p.agfxKind,frame);
 if(!im)return AGFX_drawProjectile(p);
 const size=Math.max(24,(p.r||12)*2.45)*2;
 ctx.save();ctx.translate(p.x,p.y);skillFxUpright(Math.atan2(p.vy||0,p.vx||1));
 // Cache the firebolt silhouette by animation frame and displayed size.
 // This keeps its dark edge without applying a Canvas filter to every shot.
 ctx.imageSmoothingEnabled=false;drawSpriteWithOutline(im,-size/2,-size/2,size,size);ctx.restore();
};
const AGFX_drawEffect=drawEffect;
drawEffect=function(ef){
 if(!ef.agfxKind)return AGFX_drawEffect(ef);
 const frames=ef.agfxKind==='large'?6:5;
 const progress=Math.min(.99999,Math.max(0,1-ef.t/ef.total));
 const frame=Math.min(frames,1+Math.floor(progress*frames));
 const im=agfxReady('explosion_'+ef.agfxKind,frame);
 if(!im)return AGFX_drawEffect(ef);
 const size=(ef.r||50)*(ef.agfxKind==='large'?2.4:2.15)*2;
 ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(im,ef.x-size/2,ef.y-size/2,size,size);ctx.restore();
};

