const lineFxImages={};
for(const [name,uri] of Object.entries(LINE_FX_DATA)){
 const im=new Image();im.src=uri;lineFxImages[name]=im;
}
function lineFxFrame(prefix,index){
 const count=LINE_FX_COUNTS[prefix]||0;
 if(!count)return null;
 const stem=prefix+'_'+String(Math.min(count,Math.max(1,index))).padStart(2,'0');
 const im=lineFxImages[stem+'_right']||lineFxImages[stem];
 return im?.complete&&im.naturalWidth?im:null;
}
function lineFxProjectileKind(p){
 if(!p||p.enemy||!p.owner||!p.explode)return null;
 const f=p.lineFxForm||p.owner.form;
 if(f==='greymon'&&p.element==='fire'&&p.r>=12)return'greymon';
 if(f==='metalgreymon'&&p.r>=9)return'metalgreymon';
 if(f==='wargreymon'&&p.element==='fire'&&p.r>=20)return'wargreymon';
 return null;
}
