 const g=canvas.getContext('2d');if(!g)return null;
 g.imageSmoothingEnabled=false;
 const colors=COLD_PIXEL_PALETTES[which];
 greymonPixelDisc(g,27,27,21,colors[0]);
 greymonPixelDisc(g,25,25,14,colors[1]);
