  ctx.save();ctx.imageSmoothingEnabled=false;ctx.globalAlpha*=Math.max(0,.96*(1-p));
  ctx.translate(ef.x+Math.cos(ef.a||0)*r*.52,ef.y+Math.sin(ef.a||0)*r*.52);
