 ctx.save();ctx.translate(x,y);veeFxOrientation(a);ctx.imageSmoothingEnabled=false;
 ctx.globalAlpha*=alpha;
 if(outlined)drawSpriteWithOutline(im,-w*.5,-h*.5,w,h);
