    const d=e.len*q,a=e.a+(k-2.5)*.024;
    const x=e.x+Math.cos(a)*d,y=e.y+Math.sin(a)*d;
    veeSkillSprite('pailShot',x,y,a,82,47,(1-k*.065)*f*.92);
    veeSkillSprite('pailShot',x-Math.cos(a)*47,y-Math.sin(a)*47,a,49,29,.22*f)
