  if(e.ghostClock<.045||Math.hypot(c.x-e.lastX,c.y-e.lastY)<13||effects.length>=480)continue;
  e.ghostClock=0;e.ghosts++;
  effects.push({type:'wormDashGhost',x:e.lastX,y:e.lastY,a:e.a,t:.16,total:.16});
