 const fade=progress>.76?Math.max(0,(1-progress)/.24):1;
 const half=Math.max(30,(e.w||e.width||100)*(e.guilUltPart==='finish'?1.02:.74)*.5);
 ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.a||0);ctx.globalAlpha*=fade*.94;
