 if(channel.window!==window){channel.window=window;channel.cast=rgCast(c);channel.cast.action.v111SustainedHits=Math.max(1,Math.ceil(Math.min(5,channel.total)/.2));channel.cast.action.v111SustainedBudget=.5}
